suppressPackageStartupMessages({library(data.table);library(qs);library(CellChat)})
root<-'/home/data/t070721/codex_workspace/Bladder Metabolism/mp10_subtype_screen_round3';tt<-file.path(root,'tables');objs<-qread(file.path(root,'objects/aggregated_networks.qs'));ord<-fread(file.path(tt,'node_order.tsv'));epi<-c('Epi_MP10_low','Epi_MP10_high');figs<-list();nodes_out<-list();scales<-list()
for(id in names(objs)){o<-objs[[id]];nd<-ord[network_level==o$network_level][order(node_order)];nodes<-nd$node;nn<-length(nodes);present<-rownames(o$W);coordinates<-igraph::norm_coords(igraph::layout_in_circle(igraph::make_empty_graph(nn,directed=TRUE)),xmin=-1,xmax=1,ymin=-1,ymax=1);fine<-o$network_level=='fine';folder<-if(o$scope=='ALL')file.path(root,'figures/overall')else file.path(root,'figures/by_dataset',o$scope);dir.create(folder,recursive=TRUE,showWarnings=FALSE);wd<-if(fine)24 else 11
