  draw<-function(){par(mar=c(2,2,4,2),xpd=NA);CellChat::netVisual_circle(mat,color.use=nd$color,title.name=NULL,layout=igraph::in_circle(),vertex.weight=rep(1,nn),vertex.weight.max=1,vertex.size.max=if(fine)8 else 13,vertex.label.cex=.8,vertex.label.color='#00000000',edge.weight.max=max(maxval,1e-12),edge.width.max=if(fine)6 else 8,alpha.edge=if(fine&&view=='A_full').12 else .48,edge.curved=.18,weight.scale=TRUE,top=1,remove.isolate=FALSE,shape='circle',arrow.size=if(fine).18 else .35,arrow.width=1,margin=if(fine).47 else .4)
   for(i in seq_len(nn)){xx<-coordinates[i,1];yy<-coordinates[i,2];theta<-atan2(yy,xx)*180/pi
