   };mtext(title,side=3,line=2,cex=if(fine)1.7 else 1.1);mtext(subtitle,side=3,line=.5,cex=if(fine)1.25 else .9);mtext(paste('Within-object shared scale across A/B/C:',format(maxval,digits=4),'| NE nodes are not zero | equal node size'),side=1,line=.5,cex=if(fine)1.05 else .72)
  }
  pdf(file.path(folder,paste0(stem,'.pdf')),width=wd,height=wd,bg='transparent',useDingbats=FALSE);draw();dev.off();png(file.path(folder,paste0(stem,'.png')),width=wd,height=wd,units='in',res=300,bg='transparent');draw();dev.off()
  if(o$scope%in%c('ALL','InhouseData')&&measure=='W'&&view%in%c('A_full','B_epi_to_TME')){png(file.path(root,'logs',paste0('preview_',o$scope,'_',stem,'.png')),width=2000,height=2000,res=2000/wd,bg='white');draw();dev.off()}
  rel<-substring(file.path(folder,paste0(stem,'.pdf')),nchar(root)+2);figs[[length(figs)+1]]<-data.table(path=rel,scope=o$scope,network_level=o$network_level,question=view,measure=measure,self_loops=view=='A_full',data_source='total_node_edges.tsv.gz; aggregated_networks.qs',edge_weight_max=maxval,n_display_nodes=nn,n_computed_nodes=length(present));scales[[length(scales)+1]]<-data.table(object_id=id,view=view,measure=measure,edge_weight_max=maxval,n_edges_drawn=sum(mat>0),hidden_positive_edges=0)
 }
 };nodes_out[[id]]<-data.table(object_id=id,scope=o$scope,network_level=o$network_level,node=nodes,node_order=seq_len(nn),x=coordinates[,1],y=coordinates[,2],color=nd$color,computed=nodes%in%present,node_weight=1)
 cat('Circles done',id,'\n')
}
